create extension if not exists pgcrypto;
create type booking_status as enum ('BOOKED','QUOTED','COMPLETED','CANCELLED');
create table business_settings(id uuid primary key default gen_random_uuid(), business_name text not null, phone text, email text, address text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table services(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, active boolean not null default true, created_at timestamptz not null default now());
create table vehicles(id uuid primary key default gen_random_uuid(), name text not null, category text not null, image_url text, passenger_capacity int check(passenger_capacity>0), luggage_capacity int check(luggage_capacity>=0), features text[] default '{}', description text, status text not null default 'ACTIVE', created_at timestamptz not null default now());
create table customers(id uuid primary key default gen_random_uuid(), name text not null, email text not null, phone text not null, created_at timestamptz not null default now());
create table bookings(id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id) on delete restrict, service_id uuid references services(id) on delete set null, pickup text not null, destination text not null, travel_date date not null, travel_time time not null, passengers int not null check(passengers>0), luggage int not null default 0 check(luggage>=0), vehicle_id uuid references vehicles(id) on delete set null, special_requests text, status booking_status not null default 'NEW', internal_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table booking_status_history(id uuid primary key default gen_random_uuid(), booking_id uuid not null references bookings(id) on delete cascade, old_status booking_status, new_status booking_status not null, changed_by uuid, created_at timestamptz not null default now());
create table testimonials(id uuid primary key default gen_random_uuid(), customer_name text not null, quote text not null, approved boolean not null default false, created_at timestamptz not null default now());
create table service_areas(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, active boolean not null default true);
create table admins(id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin', created_at timestamptz not null default now());
create index bookings_status_idx on bookings(status); create index bookings_date_idx on bookings(travel_date); create index bookings_customer_idx on bookings(customer_id);
alter table business_settings enable row level security; alter table services enable row level security; alter table vehicles enable row level security; alter table customers enable row level security; alter table bookings enable row level security; alter table booking_status_history enable row level security; alter table testimonials enable row level security; alter table service_areas enable row level security; alter table admins enable row level security;
create policy "public active services" on services for select using(active=true); create policy "public active vehicles" on vehicles for select using(status='ACTIVE'); create policy "public approved testimonials" on testimonials for select using(approved=true); create policy "public active areas" on service_areas for select using(active=true);
create policy "admins read customers" on customers for select to authenticated using(exists(select 1 from admins a where a.id=auth.uid())); create policy "admins manage customers" on customers for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage bookings" on bookings for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage history" on booking_status_history for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage settings" on business_settings for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage services" on services for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage vehicles" on vehicles for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage testimonials" on testimonials for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins manage areas" on service_areas for all to authenticated using(exists(select 1 from admins a where a.id=auth.uid())) with check(exists(select 1 from admins a where a.id=auth.uid()));
create policy "admins self read" on admins for select to authenticated using(id=auth.uid());
